{
  "kind": "synthetic route reasoning; no project execution",
  "cases": [
    {
      "id": "routing-verb-aliases",
      "query": "同一事实：已定位的普通内部函数错误，本轮要实际改两行代码；没有契约、安全、依赖或能力目录变化，现有实现与调用链已查明。用户分别说‘请编码修正它’、‘请实现这个修正’、‘请修改这段逻辑’、‘请修复这个错误’。逐一说明首次动手前的必读文件是否相同，是否可能只读风险分档。不要执行。"
    },
    {
      "id": "routing-fix-with-reuse",
      "query": "用户授权修复标题空白处理。项目已有已登记、适用且实际可调用的清洗能力，当前调用方复制了一份有缺陷的处理。本轮准备改调用方接入已有能力。说明要读哪些规则、查什么、哪些行为需要验证；不要执行。"
    },
    {
      "id": "routing-local-refactor",
      "query": "本轮获授权对内部函数做局部重构，未改变公开契约、权限或持久化；不抽模块，不触及已收录能力。应如何选择必读规则？是否一律要读能力库全文并创建库？不要执行。"
    },
    {
      "id": "routing-code-delete",
      "query": "用户已确认删除一个冗余内部函数，相关引用与影响已查明，不属于已收录能力。本轮只有删除，没有添加代码。动手前是否仍需实现纪律？是否自动触发能力收录？不要执行。"
    },
    {
      "id": "routing-dependency-integration",
      "query": "用户授权把项目已安装的库接入一个真实调用位置，不新增包或版本，也没有授权全局安装。说明基础读取、复用判断与实际调用验证的要求；是否仅因为叫‘依赖接入’就不用编码纪律，或必须另造包装库？不要执行。"
    },
    {
      "id": "routing-source-copy",
      "query": "用户要把Web组件源码里的按钮文字由‘保存’改为‘保存修改’，只改这一处显示文字。说明必读文件、适用检查和是否需要建立能力库；不要执行。"
    },
    {
      "id": "routing-doc-only",
      "query": "用户只改普通README介绍中的错别字，不涉及契约、运行配置、代码或产品行为。是否仅因叫‘修改’就属于代码实施并必须加载实现纪律、能力收录流程？请说明适用边界，不执行。"
    },
    {
      "id": "routing-readonly-review",
      "query": "用户只读评审一个普通内部函数的既有diff，不允许修复、安装或修改项目，也没有要求完整验收。当前阶段应读什么？是否必须按代码实施加载实现纪律并执行？不执行任何项目操作。"
    },
    {
      "id": "routing-readonly-index",
      "query": "用户只读核对项目能力索引与源码，发现索引路径可能过期，明确先不要修改。需要读能力库吗？读到补登记/索引维护规则后，可以直接修索引或创建目录吗？是否默认加载实现纪律？不要执行。"
    },
    {
      "id": "routing-readonly-acceptance",
      "query": "只读验收他人已经完成的局部修改，给定证据对应当前基线；本轮不允许改代码或CI。说明风险、验证、审查和实现纪律的读取边界，不把题设证据说成自己执行，不执行操作。"
    },
    {
      "id": "routing-authorized-transition",
      "query": "第一阶段用户只要求审查，未加载实现纪律。第二阶段用户明确授权修复已经定位的已收录能力调用错误。分别说明两个阶段的读取与权限；第二阶段第一次修改前需补什么？如果没有第二次授权又如何？不要实际修改。"
    },
    {
      "id": "routing-thick-implementation",
      "query": "本轮实际代码修复已经正确判为厚审大改。Agent计划只按照风险表中的编码前、验证与审查清单做完就开始写代码。请判断读取是否足够，并列基础与追加要求；没有新收录对象的事实，不要强制造库。不要执行。"
    },
    {
      "id": "routing-first-capability",
      "query": "用户真实要求新增一个功能。现有索引和源码已检查，没有适用实现；其中确有输入、输出、依赖和副作用边界明确的可复用能力，只有一个真实调用方，项目已有能力模块位置。应该读取哪些规则，何时收录，是否要等第二个调用方？不要执行。"
    },
    {
      "id": "routing-private-orchestration",
      "query": "用户要求实现页面私有编排，已查现有能力和源码。本次没有能独立封装的可复用对象，沿用页面内部编排即可。实现功能会触发读能力库规则吗？是否因此必须创建目录、抽模块、补一份空索引？不要执行。"
    }
  ]
}
